        raise ValueError('class must be "MultinomialLogisticRegression"')

    lr = _expect_fixed(data["lr"], "lr")
    if lr <= 0.0:
        raise ValueError("lr must be greater than 0")
    l2 = _expect_fixed(data["l2"], "l2")
